"""Flask REST API for the Quest Runner service."""

from __future__ import annotations

import logging
from collections.abc import Callable
from pathlib import Path

from flask import Flask, jsonify, request, send_from_directory

from . import dashboard_data
from . import dashboard_git
from . import dashboard_slice
from .harness import HarnessNotAvailable
from .quest_fs import QuestStateParseError
from .quest_service import (
    FatalInvariantError,
    InvalidProject,
    InvalidQuestInput,
    MissingDefaultExecutionConfig,
    MissingQuestWorktree,
    NotAGitRepo,
    QuestLockContention,
    QuestNotFound,
    QuestService,
    RepoNotFound,
)
from .worktrees import WorktreeCreationError

log = logging.getLogger("quest_runner")
_DASHBOARD_ASSETS_DIR = Path(__file__).resolve().parent / "dashboard_assets"


def _no_cache(resp):
    resp.headers["Cache-Control"] = "no-store, no-cache, must-revalidate, max-age=0"
    resp.headers["Pragma"] = "no-cache"
    resp.headers["Expires"] = "0"
    return resp


def create_app(
    quest_service: QuestService,
    source_repo_root: Path,
    started_at: float,
    shutdown_callback: Callable[[], None] | None = None,
) -> Flask:
    app = Flask(__name__)
    source_root = source_repo_root.resolve()

    @app.errorhandler(RepoNotFound)
    def handle_repo_not_found(exc):
        return jsonify({"error": str(exc)}), 404

    @app.errorhandler(NotAGitRepo)
    def handle_not_git_repo(exc):
        return jsonify({"error": str(exc)}), 422

    @app.errorhandler(InvalidProject)
    def handle_invalid_project(exc):
        return jsonify({"error": str(exc)}), 400

    @app.errorhandler(InvalidQuestInput)
    def handle_invalid_quest_input(exc):
        return jsonify({"error": str(exc)}), 400

    @app.errorhandler(QuestLockContention)
    def handle_lock_contention(exc):
        return jsonify({
            "error": str(exc),
            "repo_path": exc.repo_path,
            "lock_owner": {
                "quest_type": exc.lock_info.quest_type,
                "quest_number": exc.lock_info.quest_number,
                "request_id": exc.lock_info.request_id,
            },
        }), 409

    @app.errorhandler(QuestNotFound)
    def handle_quest_not_found(exc):
        return jsonify({"error": str(exc)}), 404

    @app.errorhandler(MissingQuestWorktree)
    def handle_missing_quest_worktree(exc):
        return jsonify({
            "error": str(exc),
            "project": exc.project,
            "quest_type": exc.quest_type,
            "quest_number": exc.quest_number,
            "expected_worktree": str(exc.worktree_path),
        }), 409

    @app.errorhandler(FatalInvariantError)
    def handle_fatal_invariant(exc):
        return jsonify({"error": str(exc)}), 500

    @app.errorhandler(MissingDefaultExecutionConfig)
    def handle_missing_default_execution_config(exc):
        return jsonify({"error": str(exc)}), 500

    @app.errorhandler(WorktreeCreationError)
    def handle_worktree_creation_error(exc):
        return jsonify({"error": str(exc)}), 500

    @app.errorhandler(HarnessNotAvailable)
    def handle_harness_not_available(exc):
        return jsonify({"error": str(exc)}), 503

    @app.errorhandler(QuestStateParseError)
    def handle_quest_state_parse_error(exc):
        return jsonify({"error": str(exc)}), 422

    @app.errorhandler(dashboard_data.DashboardBadRequest)
    def handle_dashboard_bad_request(exc):
        body: dict = {"error": exc.message}
        if exc.fields:
            body["fields"] = exc.fields
        return jsonify(body), 400

    @app.errorhandler(dashboard_data.DashboardNotFound)
    def handle_dashboard_not_found(exc):
        return jsonify({"error": exc.message}), 404

    @app.before_request
    def log_request() -> None:
        log.info("HTTP %s %s", request.method, request.path)

    @app.route("/health", methods=["GET"])
    def health():
        import time

        return jsonify({
            "healthy": True,
            "uptime": round(time.time() - started_at, 2),
        }), 200

    @app.route("/exit", methods=["POST"])
    def exit_service():
        if shutdown_callback is not None:
            shutdown_callback()
        else:
            import os
            import threading

            def _exit_process() -> None:
                os._exit(0)

            timer = threading.Timer(0.1, _exit_process)
            timer.daemon = True
            timer.start()
        return jsonify({"status": "exiting"}), 200

    @app.route("/create_quest", methods=["POST"])
    def create_quest_route():
        data = request.get_json(force=True)
        required = ["project", "quest_type", "name"]
        missing = [f for f in required if f not in data]
        if missing:
            return jsonify({"error": f"Missing required fields: {missing}"}), 400
        log.info(
            "create_quest project=%s type=%s name=%s",
            data["project"],
            data["quest_type"],
            data["name"],
        )
        result = quest_service.create_quest(
            repo_path=str(source_root),
            project=data["project"],
            quest_type=data["quest_type"],
            name=data["name"],
            slug=data.get("slug"),
            requested_by=data.get("requested_by"),
        )
        log.info(
            "create_quest ok project=%s type=%s number=%s worktree=%s",
            result["project"],
            result["quest_type"],
            result["quest_number"],
            result.get("worktree_path"),
        )
        return jsonify(result), 201

    @app.route("/run_quest", methods=["POST"])
    def run_quest_route():
        data = request.get_json(force=True)
        required = ["project", "quest_type", "quest_number"]
        missing = [f for f in required if f not in data]
        if missing:
            return jsonify({"error": f"Missing required fields: {missing}"}), 400
        try:
            max_steps = dashboard_data.parse_max_steps(data.get("max_steps"))
        except dashboard_data.DashboardBadRequest as exc:
            return jsonify({"error": exc.message, "fields": exc.fields}), 400
        log.info(
            "run_quest project=%s type=%s number=%s max_steps=%s",
            data["project"],
            data["quest_type"],
            data["quest_number"],
            max_steps,
        )
        base = request.url_root
        result = quest_service.schedule_run_quest(
            repo_path=str(source_root),
            project=data["project"],
            quest_type=data["quest_type"],
            quest_number=data["quest_number"],
            max_steps=max_steps,
            public_base_url=base,
        )
        log.info(
            "run_quest scheduled run_id=%s status=%s",
            result.get("run_id"),
            result.get("status"),
        )
        return jsonify(result), 202

    @app.route("/dashboard", methods=["GET"])
    def dashboard_shell():
        return _no_cache(
            send_from_directory(
                _DASHBOARD_ASSETS_DIR,
                "index.html",
                conditional=False,
                max_age=0,
            )
        )

    @app.route("/dashboard/assets/<path:filename>", methods=["GET"])
    def dashboard_static(filename: str):
        return _no_cache(
            send_from_directory(
                _DASHBOARD_ASSETS_DIR,
                filename,
                conditional=False,
                max_age=0,
            )
        )

    def _quest_context():
        project = dashboard_data.parse_project(
            request.args.get("project"),
            source_repo_root=source_root,
        )
        qt = dashboard_data.parse_quest_type(request.args.get("quest_type"))
        qn = dashboard_data.parse_quest_number(request.args.get("quest_number"))
        checkout, qdir = dashboard_data.resolve_quest_dirs(
            source_root, project, qt, qn
        )
        return project, qt, qn, qdir, checkout

    @app.route("/api/dashboard/projects", methods=["GET"])
    def dashboard_projects():
        payload = dashboard_data.projects_payload(source_root)
        return jsonify(payload)

    @app.route("/api/dashboard/project_snapshot", methods=["GET"])
    def dashboard_project_snapshot():
        project = dashboard_data.parse_project(
            request.args.get("project"),
            source_repo_root=source_root,
        )
        payload = dashboard_data.project_snapshot_payload(
            source_repo_root=source_root,
            project=project,
            lock=quest_service.lock,
        )
        return jsonify(payload)

    @app.route("/api/dashboard/quest_overview", methods=["GET"])
    def dashboard_quest_overview():
        project, _qt, _qn, qdir, checkout = _quest_context()
        base = request.url_root
        payload = dashboard_data.quest_overview_payload(
            quest_dir=qdir,
            source_repo_root=source_root,
            checkout_root=checkout,
            project=project,
            lock=quest_service.lock,
            public_base_url=base,
        )
        return jsonify(payload)

    @app.route("/api/dashboard/physicalplan_issues", methods=["GET"])
    def dashboard_physicalplan_issues():
        _project, _qt, _qn, qdir, _checkout = _quest_context()
        return jsonify(dashboard_data.physicalplan_issues_payload(qdir))

    @app.route("/api/dashboard/human_intervention", methods=["GET"])
    def dashboard_human_intervention():
        _project, _qt, _qn, qdir, _checkout = _quest_context()
        return jsonify(dashboard_data.human_intervention_payload(qdir))

    @app.route("/api/dashboard/run_status", methods=["GET"])
    def dashboard_run_status():
        project, qt, qn, qdir, _checkout = _quest_context()
        payload = dashboard_data.run_status_payload(
            quest_dir=qdir,
            source_repo_root=source_root,
            project=project,
            quest_type=qt,
            quest_number=qn,
            lock=quest_service.lock,
            run_tracker=quest_service.run_tracker,
        )
        return jsonify(payload)

    @app.route("/api/dashboard/slice_page", methods=["GET"])
    def dashboard_slice_page():
        _project, _qt, _qn, qdir, _checkout = _quest_context()
        sn = dashboard_slice.parse_slice_number(request.args.get("slice_number"))
        sub = dashboard_slice.parse_subpage(request.args.get("subpage"))
        payload = dashboard_slice.slice_page_payload(
            quest_dir=qdir,
            slice_number=sn,
            subpage=sub,
        )
        return jsonify(payload)

    @app.route("/api/dashboard/quest_agents", methods=["GET"])
    def dashboard_quest_agents():
        _project, _qt, _qn, qdir, _checkout = _quest_context()
        return jsonify(dashboard_slice.quest_agents_payload(qdir))

    @app.route("/api/dashboard/agent_log", methods=["GET"])
    def dashboard_agent_log():
        _project, _qt, _qn, qdir, _checkout = _quest_context()
        ak = request.args.get("agent_key")
        step = dashboard_slice.parse_optional_step(request.args.get("step"))
        payload = dashboard_slice.agent_log_payload(
            quest_dir=qdir,
            agent_key=ak or "",
            step=step,
        )
        return jsonify(payload)

    @app.route("/api/dashboard/git_commits", methods=["GET"])
    def dashboard_git_commits():
        _project, _qt, _qn, _qdir, checkout = _quest_context()
        limit = dashboard_git.parse_limit(request.args.get("limit"))
        skip = dashboard_git.parse_skip(request.args.get("skip"))
        payload = dashboard_git.git_commits_payload(
            checkout, limit=limit, skip=skip
        )
        return jsonify(payload)

    @app.route("/api/dashboard/git_diff", methods=["GET"])
    def dashboard_git_diff():
        _project, _qt, _qn, _qdir, checkout = _quest_context()
        commit = request.args.get("commit")
        if commit is None or not str(commit).strip():
            raise dashboard_data.DashboardBadRequest(
                "Missing required query parameter: commit",
                fields={"commit": "required"},
            )
        path = request.args.get("path")
        if path is not None and str(path).strip():
            payload = dashboard_git.git_diff_file_payload(
                checkout, commit.strip(), str(path).strip()
            )
        else:
            payload = dashboard_git.git_diff_summary_payload(
                checkout, commit.strip()
            )
        return jsonify(payload)

    return app

"""Dashboard query validation, filesystem reads, and JSON-oriented payloads."""

from __future__ import annotations

import re
from dataclasses import dataclass
from datetime import datetime, timezone
from pathlib import Path
from urllib.parse import quote, urlencode

from . import quest_fs
from .dashboard_runs import ActiveRunTracker
from .quest_lock import QuestLock
from .quest_types import IssueEntry, QuestMeta, QuestState, slice_index_from_dirname
from .worktrees import quest_worktree_path, validate_project_name, worktree_exists

_RESPONSE_SECTION_RE = re.compile(
    r"^## Response\s+(\S+)\s+(.+)\s*$",
    re.MULTILINE,
)
_PAUSED_UNTIL_LINE_RE = re.compile(
    r"^\s*Paused\s+until\s+(.+?)\s*$",
    re.IGNORECASE | re.MULTILINE,
)


class DashboardBadRequest(Exception):
    def __init__(self, message: str, *, fields: dict | None = None) -> None:
        self.message = message
        self.fields = fields or {}
        super().__init__(message)


class DashboardNotFound(Exception):
    def __init__(self, message: str) -> None:
        self.message = message
        super().__init__(message)


def quote_query_param(value: str) -> str:
    return quote(value, safe="")


def canonical_quest_dashboard_url(
    *,
    base_url: str,
    project: str,
    quest_type: str,
    quest_number: int,
) -> str:
    q = urlencode(
        {
            "project": project,
            "quest_type": quest_type,
            "quest_number": str(quest_number),
        }
    )
    return f"{base_url.rstrip('/')}/dashboard?{q}"


def parse_project(
    raw: str | None,
    *,
    source_repo_root: Path | None = None,
) -> str:
    if raw is None or not str(raw).strip():
        raise DashboardBadRequest(
            "Missing required query parameter: project",
            fields={"project": "required"},
        )
    project = str(raw).strip()
    try:
        validate_project_name(project)
    except ValueError as e:
        raise DashboardBadRequest(str(e), fields={"project": "invalid"}) from e
    if source_repo_root is not None:
        project_dir = source_repo_root / "projects" / project
        if not project_dir.is_dir():
            raise DashboardNotFound(f"Project not found: {project!r}")
    return project


def parse_max_steps(raw: object | None, *, default: int = 500) -> int:
    if raw is None:
        return default
    if not isinstance(raw, int) or raw < 1:
        raise DashboardBadRequest(
            "max_steps must be a positive integer",
            fields={"max_steps": "invalid"},
        )
    return raw


def lock_key_for_quest(source_repo_root: Path, meta: QuestMeta) -> str:
    from .quest_service import _build_run_lock_key

    worktree_path = quest_worktree_path(source_repo_root, meta).resolve()
    return _build_run_lock_key(
        worktree_path,
        meta.project,
        meta.quest_type,
        meta.quest_number,
    )


def resolve_quest_checkout_root(source_repo_root: Path, quest_dir: Path) -> Path:
    meta = quest_fs.read_quest_meta(quest_dir)
    if worktree_exists(source_repo_root, meta):
        return quest_worktree_path(source_repo_root, meta).resolve()
    return source_repo_root.resolve()


def resolve_quest_dirs(
    source_repo_root: Path,
    project: str,
    quest_type: str,
    quest_number: int,
) -> tuple[Path, Path]:
    source_qdir = resolve_quest_dir(
        source_repo_root, project, quest_type, quest_number
    )
    checkout_root = resolve_quest_checkout_root(source_repo_root, source_qdir)
    quest_dir = source_qdir
    if checkout_root != source_repo_root.resolve():
        worktree_qdir = quest_fs.find_quest_dir(
            checkout_root, project, quest_type, quest_number
        )
        if worktree_qdir is not None:
            quest_dir = worktree_qdir
    return checkout_root, quest_dir


def projects_payload(source_repo_root: Path) -> dict:
    roots = quest_fs.iter_project_quest_roots(source_repo_root)
    projects = [{"project": root.project} for root in roots]
    default_project = roots[0].project if roots else None
    return {
        "projects": projects,
        "default_project": default_project,
    }


@dataclass
class PauseUntilState:
    kind: str
    until_iso: str | None = None


def read_paused_until_state(quest_dir: Path) -> PauseUntilState:
    path = quest_dir / "paused_until.md"
    if not path.is_file():
        return PauseUntilState(kind="absent")
    text = path.read_text(encoding="utf-8")
    m = _PAUSED_UNTIL_LINE_RE.search(text)
    if not m:
        return PauseUntilState(kind="invalid")
    raw_ts = m.group(1).strip()
    try:
        normalized = raw_ts.replace("Z", "+00:00")
        dt = datetime.fromisoformat(normalized)
        if dt.tzinfo is None:
            dt = dt.replace(tzinfo=timezone.utc)
        until = dt.astimezone(timezone.utc)
    except ValueError:
        return PauseUntilState(kind="invalid")
    until_iso = until.strftime("%Y-%m-%dT%H:%M:%SZ")
    now = datetime.now(timezone.utc)
    if until > now:
        return PauseUntilState(kind="active", until_iso=until_iso)
    return PauseUntilState(kind="expired", until_iso=until_iso)


def execution_overlay_status(
    *,
    quest_dir: Path,
    lock_key: str,
    quest_type: str,
    quest_number: int,
    lock: QuestLock,
) -> str:
    if quest_fs.has_human_intervention_request(quest_dir):
        return "human_intervention"
    pause = read_paused_until_state(quest_dir)
    if pause.kind == "invalid":
        return "human_intervention"
    if pause.kind == "active":
        return "paused"
    info = lock.get_lock_info(lock_key)
    if (
        info is not None
        and info.quest_type == quest_type
        and info.quest_number == quest_number
    ):
        return "running"
    return "none"


def paused_until_public(pause: PauseUntilState) -> str | None:
    if pause.kind == "active":
        return pause.until_iso
    return None


def issue_status_counts(issues: list[IssueEntry]) -> dict[str, int]:
    open_n = sum(1 for i in issues if i.status == "open")
    completed_n = sum(1 for i in issues if i.status == "completed")
    return {"open": open_n, "completed": completed_n}


def issues_latest_updated_at(issues: list[IssueEntry]) -> str | None:
    if not issues:
        return None
    return max(i.updated_at for i in issues)


def find_slice_dir(quest_dir: Path, slice_number: int) -> Path | None:
    for p in quest_fs.list_slice_dirs(quest_dir):
        if slice_index_from_dirname(p.name) == slice_number:
            return p
    return None


def resolve_quest_dir(
    source_repo_root: Path,
    project: str,
    quest_type: str,
    quest_number: int,
) -> Path:
    qdir = quest_fs.find_quest_dir(source_repo_root, project, quest_type, quest_number)
    if qdir is None:
        raise DashboardNotFound(
            f"No quest found for project={project!r} type={quest_type!r} "
            f"number={quest_number}"
        )
    return qdir


def parse_quest_type(raw: str | None) -> str:
    if raw is None or not str(raw).strip():
        raise DashboardBadRequest(
            "Missing required query parameter: quest_type",
            fields={"quest_type": "required"},
        )
    if raw not in ("main", "side"):
        raise DashboardBadRequest(
            "quest_type must be 'main' or 'side'",
            fields={"quest_type": "invalid"},
        )
    return raw


def parse_quest_number(raw: str | None) -> int:
    if raw is None or not str(raw).strip():
        raise DashboardBadRequest(
            "Missing required query parameter: quest_number",
            fields={"quest_number": "required"},
        )
    try:
        n = int(raw, 10)
    except ValueError as e:
        raise DashboardBadRequest(
            "quest_number must be an integer",
            fields={"quest_number": "invalid"},
        ) from e
    if n < 0:
        raise DashboardBadRequest(
            "quest_number must be non-negative",
            fields={"quest_number": "invalid"},
        )
    return n


@dataclass
class PhysicalPlanResponseEntry:
    issue_id: str
    response_timestamp: str
    outcome: str
    explanation: str


def read_physicalplan_issue_responses(quest_dir: Path) -> list[PhysicalPlanResponseEntry]:
    path = quest_dir / "physicalplan_issue_responses.md"
    if not path.is_file():
        return []
    text = path.read_text(encoding="utf-8")
    matches = list(_RESPONSE_SECTION_RE.finditer(text))
    if not matches:
        return []
    out: list[PhysicalPlanResponseEntry] = []
    for i, m in enumerate(matches):
        issue_id_heading = m.group(1)
        ts = m.group(2).strip()
        start = m.end()
        end = matches[i + 1].start() if i + 1 < len(matches) else len(text)
        body = text[start:end]
        fields: dict[str, str] = {}
        current: str | None = None
        for raw_line in body.split("\n"):
            line = raw_line.strip()
            if line.startswith("- ") and ":" in line:
                rest = line[2:].strip()
                key, _, val = rest.partition(":")
                key = key.strip()
                val = val.strip()
                current = key
                fields[current] = val
            elif current == "explanation" and line:
                fields[current] = fields.get(current, "") + "\n" + raw_line.rstrip("\n")
            elif current == "explanation" and not line:
                fields[current] = fields.get(current, "") + "\n"
        expl = fields.get("explanation", "").strip()
        out.append(
            PhysicalPlanResponseEntry(
                issue_id=fields.get("issue_id", issue_id_heading),
                response_timestamp=ts,
                outcome=fields.get("outcome", ""),
                explanation=expl,
            )
        )
    return out


def issue_entry_to_card(entry: IssueEntry) -> dict:
    return {
        "issue_id": entry.issue_id,
        "status": entry.status,
        "owner_role": entry.owner_role,
        "created_at": entry.created_at,
        "updated_at": entry.updated_at,
        "title": entry.title,
        "details": entry.details,
        "resolution_notes": entry.resolution_notes,
    }


def summarize_responses_for_issues(
    issues: list[IssueEntry],
    responses: list[PhysicalPlanResponseEntry],
) -> list[dict]:
    ids = {i.issue_id for i in issues}
    matched = [r for r in responses if r.issue_id in ids]
    return [
        {
            "issue_id": r.issue_id,
            "response_timestamp": r.response_timestamp,
            "outcome": r.outcome,
            "explanation_preview": r.explanation[:500]
            + ("…" if len(r.explanation) > 500 else ""),
        }
        for r in matched
    ]


def human_intervention_payload(quest_dir: Path) -> dict:
    path = quest_dir / "human_intervention_request.md"
    if not path.is_file():
        return {
            "present": False,
            "markdown": None,
            "path": "human_intervention_request.md",
            "updated_at": None,
        }
    st = path.stat()
    updated = datetime.fromtimestamp(st.st_mtime, tz=timezone.utc).strftime(
        "%Y-%m-%dT%H:%M:%SZ"
    )
    return {
        "present": True,
        "markdown": path.read_text(encoding="utf-8"),
        "path": "human_intervention_request.md",
        "updated_at": updated,
    }


def physicalplan_issues_payload(quest_dir: Path) -> dict:
    path = quest_dir / "physicalplan_issues.md"
    issues = quest_fs.read_issues(path)
    counts = issue_status_counts(issues)
    responses = read_physicalplan_issue_responses(quest_dir)
    latest = issues_latest_updated_at(issues)
    resp_ts = [r.response_timestamp for r in responses]
    latest_response_ts = max(resp_ts) if resp_ts else None
    latest_updates = [x for x in (latest, latest_response_ts) if x]
    latest_overall = max(latest_updates) if latest_updates else None
    return {
        "issues_path": "physicalplan_issues.md",
        "issues": [issue_entry_to_card(i) for i in issues],
        "open_count": counts["open"],
        "completed_count": counts["completed"],
        "latest_issue_updated_at": latest,
        "latest_response_updated_at": latest_response_ts,
        "latest_update_at": latest_overall,
        "responses_summary": summarize_responses_for_issues(issues, responses),
    }


def quest_summary_row(
    *,
    quest_dir: Path,
    source_repo_root: Path,
    lock: QuestLock,
    meta: QuestMeta,
) -> dict:
    lock_key = lock_key_for_quest(source_repo_root, meta)
    state_info = quest_fs.read_quest_state(quest_dir)
    pause = read_paused_until_state(quest_dir)
    overlay = execution_overlay_status(
        quest_dir=quest_dir,
